"use client";

import { useParams } from "next/navigation";
import ProductPageClient from "./ProductPageClient";

// Для статического экспорта требуется generateStaticParams
// Возвращаем пустой массив, так как мы не знаем все slug заранее
// Страницы будут генерироваться динамически на клиенте
export const generateStaticParams = async () => {
  return [];
};

// Разрешаем динамические параметры
export const dynamicParams = true;

const ProductPage = () => {
  const params = useParams();
  const slug = params?.slug as string;

  if (!slug) {
    return null;
  }

  return <ProductPageClient slug={slug} />;
};

export default ProductPage;
